import { useEffect, useRef, useState } from 'react';
import { useScrollAnimation } from '../hooks/useScrollAnimation';
import profileImage from '../assets/picture.jpg';
import './AboutMe.css';

const stats = [
  { value: 3,    suffix: '+', label: 'Years Experience' },
  { value: 10,   suffix: '+', label: 'Projects Built'   },
  { value: 15,   suffix: '+', label: 'Technologies'     },
  { value: 3,    suffix: '',  label: 'Countries Worked'  },
];

const tools = ['Python','C#','React','TypeScript','Node.js','Angular','Flask','PostgreSQL','MySQL','Docker','AWS','GCP','TensorFlow','PyTorch'];

function CountUp({ target, suffix }) {
  const [count, setCount] = useState(0);
  const ref = useRef(null);
  const [started, setStarted] = useState(false);

  useEffect(() => {
    const obs = new IntersectionObserver(
      ([e]) => { if (e.isIntersecting) setStarted(true); },
      { threshold: 0.6 }
    );
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, []);

  useEffect(() => {
    if (!started) return;
    let cur = 0;
    const step = target / 40;
    const t = setInterval(() => {
      cur += step;
      if (cur >= target) { setCount(target); clearInterval(t); }
      else setCount(Math.ceil(cur));
    }, 35);
    return () => clearInterval(t);
  }, [started, target]);

  return <span ref={ref}>{count}{suffix}</span>;
}

const AboutMe = () => {
  const [headerRef, headerIn] = useScrollAnimation();
  const [imgRef,    imgIn]    = useScrollAnimation();
  const [textRef,   textIn]   = useScrollAnimation();

  return (
    <section id="about-me" className="about-section">
      <div className="container">
        <div ref={headerRef} className={`about-header animate ${headerIn ? 'in-view' : ''}`}>
          <span className="section-label">About Me</span>
          <h2 className="section-title">
            Building things that <span className="gradient-text">matter</span>
          </h2>
        </div>

        <div className="about-body">
          <div ref={imgRef} className={`about-image-col animate ${imgIn ? 'in-view' : ''}`}>
            <div className="about-img-frame">
              <img src={profileImage} alt="Shashank Shankaregowda" className="about-img" />
              <div className="img-badge">
                <span className="img-badge-icon">🎓</span>
                <div>
                  <p className="img-badge-title">MS Computer Science</p>
                  <p className="img-badge-sub">University at Buffalo</p>
                </div>
              </div>
            </div>
          </div>

          <div ref={textRef} className={`about-text-col animate d2 ${textIn ? 'in-view' : ''}`}>
            <p className="about-para">
              I'm a Software Engineer with a Master's degree in Computer Science from the University at Buffalo,
              specializing in Artificial Intelligence. My work sits at the intersection of scalable backend systems
              and intelligent data-driven solutions.
            </p>
            <p className="about-para">
              At Datalyzer International and BrightChamps, I led the design of RESTful APIs, optimized relational
              databases, built cloud billing analysis tools on GCP, and delivered front-end improvements that cut
              page load times by 50% and reduced system downtime by 30%. Currently, I'm contributing to full-stack
              development at Holiday Channel in Colorado as a Software Engineer Intern.
            </p>
            <p className="about-para">
              Outside of engineering, I have a passion for teaching—I spent over a year as a coding instructor,
              guiding students through HTML, CSS, JavaScript, and Python to build real-world applications.
            </p>

            <div className="stats-row">
              {stats.map((s, i) => (
                <div key={i} className="stat-item">
                  <span className="stat-value gradient-text">
                    <CountUp target={s.value} suffix={s.suffix} />
                  </span>
                  <span className="stat-label">{s.label}</span>
                </div>
              ))}
            </div>

            <div className="tools-row">
              <p className="tools-label">I work with</p>
              <div className="tools-tags">
                {tools.map(t => <span key={t} className="tag">{t}</span>)}
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default AboutMe;
